import random
from itertools import combinations

def has_short_cycle(adj, n, max_len=5):
    # BFS from each vertex; if we find a cycle of length <= max_len
    for s in range(n):
        # BFS, track parent
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                if dist[u] > max_len//2 + 1:
                    continue
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nq.append(v)
                    elif v != parent[u]:
                        # found a cycle of length dist[u]+dist[v]+1
                        cyc = dist[u]+dist[v]+1
                        if cyc <= max_len:
                            return True
            queue = nq
    return False

def try_build(n=23, seed=0, min_d=3, max_d=6, girth_min=6):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = list(combinations(range(n), 2))
    random.shuffle(edges)
    for u,v in edges:
        if len(adj[u]) >= max_d or len(adj[v]) >= max_d:
            continue
        # check if adding edge creates cycle of length < girth_min
        # distance between u and v in current graph must be >= girth_min - 1
        # BFS from u
        dist = {u:0}
        frontier = [u]
        found = False
        for _ in range(girth_min-2):
            nf = []
            for x in frontier:
                for y in adj[x]:
                    if y not in dist:
                        dist[y] = dist[x]+1
                        nf.append(y)
            frontier = nf
        if v in dist:
            continue
        adj[u].add(v); adj[v].add(u)
    # check min degree
    degs = [len(a) for a in adj]
    if min(degs) >= min_d:
        return adj
    return None

for seed in range(1000):
